const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, Footer, AlignmentType, LevelFormat, ExternalHyperlink,
  HeadingLevel, BorderStyle, WidthType, ShadingType, PageNumber, PageBreak, VerticalAlign
} = require("docx");
const brand = require("./brand.js");

const CONTENT_WIDTH = 9360;
const border = { style: BorderStyle.SINGLE, size: 2, color: "CCCCCC" };
const borders = { top: border, bottom: border, left: border, right: border };

function h1(text) { return new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(text)] }); }
function h2(text) { return new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun(text)] }); }
function h3(text) { return new Paragraph({ heading: HeadingLevel.HEADING_3, children: [new TextRun(text)] }); }
function p(text, opts = {}) { return new Paragraph({ spacing: { after: 160 }, children: [new TextRun({ text, ...opts })] }); }
function bullet(text, level = 0) { return new Paragraph({ numbering: { reference: "bullets", level }, spacing: { after: 60 }, children: [new TextRun(text)] }); }
function spacer(h) { return new Paragraph({ spacing: { after: h || 200 }, children: [] }); }

// A ToDo item: an open checkbox, the item text, and a small context tag.
function todoItem(text, context) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 }, spacing: { after: 80 },
    children: [
      new TextRun({ text: "☐ ", bold: true }),
      new TextRun({ text }),
      context ? new TextRun({ text: "  (" + context + ")", italics: true, color: "777777", size: 18 }) : new TextRun({ text: "" }),
    ],
  });
}
// A resolved ToDo item - kept struck through briefly, meant to be deleted outright at the next consolidation pass.
function doneItem(text, context) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 }, spacing: { after: 80 },
    children: [
      new TextRun({ text: "☑ ", bold: true, color: "1B7A3D" }),
      new TextRun({ text, strike: true, color: "888888" }),
      context ? new TextRun({ text: "  (" + context + ")", italics: true, color: "AAAAAA", size: 18 }) : new TextRun({ text: "" }),
    ],
  });
}
// A note entry - a short bold label, then freeform commentary. Append-only; don't rewrite old ones except at a consolidation pass.
function noteEntry(label, text, context) {
  return new Paragraph({
    spacing: { after: 200 },
    children: [
      new TextRun({ text: label + ": ", bold: true, color: brand.NAVY2 }),
      new TextRun({ text }),
      context ? new TextRun({ text: "  [" + context + "]", italics: true, color: "999999", size: 18 }) : new TextRun({ text: "" }),
    ],
  });
}

const numberingConfig = {
  config: [
    { reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },
    { reference: "numbers", levels: [{ level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },
  ]
};

// =========================================================================
// ToDo items - update or delete in place as they're actually resolved.
// Add new ones freely; don't feel obligated to re-sort or re-group them
// as you go - that's what the periodic consolidation pass is for.
